#include "KS/SRC/physical_interface_shared.h"

#define IFC_INTERNAL_FUNC_MACRO(a,b) { static pstring pstring_func(a); if(att == pstring_func) { b; return(true); } }

bool physical_interface::set_ifc_vec(const pstring &att, const vector3d &val)
{
  IFC_INTERNAL_FUNC_MACRO("VELOCITY", set_velocity(val));
  IFC_INTERNAL_FUNC_MACRO("ANGULAR_VELOCITY", set_angular_velocity(val));

  return(false);
}

typedef unsigned long uint64;

class pstring
{
  uint64 pchunk[4];
  void pack_string(const char *the_string);
public:
  pstring(const char *target_string) { pack_string(target_string); }
  bool operator == (const pstring &check_me) const
  {
    for (unsigned i=0; i<4; ++i)
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    return true;
  }
};

class vector3d
{
public:
  float x, y, z;
  vector3d& operator=(const vector3d& v)
  {
    x = v.x; y = v.y; z = v.z;
    return *this;
  }
};

class physical_interface
{
  char prefix[20];
  vector3d velocity;
  vector3d angular_velocity;
public:
  void set_velocity(const vector3d &value) { velocity = value; }
  void set_angular_velocity(const vector3d &value) { angular_velocity = value; }
  bool set_ifc_vec(const pstring &att, const vector3d &val);
};

#define IFC_INTERNAL_FUNC_MACRO(a,b) { static pstring pstring_func(a); if(att == pstring_func) { b; return(true); } }

bool physical_interface::set_ifc_vec(const pstring &att, const vector3d &val)
{
  IFC_INTERNAL_FUNC_MACRO("VELOCITY", set_velocity(val));
  IFC_INTERNAL_FUNC_MACRO("ANGULAR_VELOCITY", set_angular_velocity(val));

  return(false);
}

